local mapper = mapper
local config_ethoam = "ethoam"

-- uci.ethoam
mapper("uci_1to1").registerConfigMap(config_ethoam)

-- uci.ethoam.global.
local ethoam_global  = {
    config = config_ethoam,
    section = "global",
    type = "ethoam",
    options = { "enable" },
    lists = { "configurations" },
}

mapper("uci_1to1").registerSimpleMap(ethoam_global)

-- uci.ethoam.configuration
local ethoam_configuration = {
  config = config_ethoam,
  type = "configuration",
  options = { "type", "mepId", "meg", "megLevel", "vlan", "ifname", "oamID", "features", }
}

mapper("uci_1to1").registerNamedMultiMap(ethoam_configuration)


